   "path": "徐总问题专题库/02_企业AI与商业化/2026-08-18_企业AI落地问题总和：战略-机制-卡点三层融合.md",
   "title": "企业AI落地问题总和：战略-机制-卡点三层融合",
   "date": "2026-08-18",
